WITH metrics AS (SELECT *, AVG(units) OVER (PARTITION BY store_id) AS store_id_avg_units, ROUND(units / SUM(units) OVER (PARTITION BY store_id), 4) AS units_share, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id, store_id), 4) AS revenue_share FROM store_sales) SELECT id, store_id, product_id, sale_date, revenue, store_id_avg_units, units_share FROM metrics ORDER BY store_id_avg_units DESC NULLS FIRST, units_share;
